const D = { density: .5, scale: 1, energy: .55, glow: .7, dust: 3, hue: 18, speed: 1, x: .68, y: .58, style: 'ochre', act: 'day', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 18;
const lerp3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];

const STY = {
  ochre:     { sky:[[20,42,48],[18,54,58],[26,64,62]], dune:[[16,58,42],[14,54,30],[12,50,20]], dome:[30,70,70], glass:[34,30,90], moon:[28,14,70], dust:[24,40,72], line:false, halftone:false },
  blueprint: { sky:[[210,72,14],[212,64,20],[214,56,26]], dune:[[208,58,20],[210,54,15],[212,50,11]], dome:[190,26,96], glass:[190,40,80], moon:[190,20,90], dust:[196,40,54], line:true, halftone:false },
  thermal:   { sky:[[238,56,10],[230,50,16],[220,46,22]], dune:[[210,44,20],[218,42,14],[226,40,9]], dome:[20,92,96], glass:[46,90,94], moon:[54,70,86], dust:[8,80,84], line:false, halftone:false },
  riso:      { sky:[[32,20,88],[26,34,80],[20,44,72]], dune:[[12,72,64],[10,74,52],[8,72,42]], dome:[350,64,80], glass:[36,44,92], moon:[350,40,80], dust:[10,60,74], line:false, halftone:true },
  nocturne:  { sky:[[250,48,10],[244,44,16],[18,40,24]], dune:[[254,40,16],[250,38,11],[246,36,8]], dome:[30,74,66], glass:[40,50,84], moon:[46,20,84], dust:[250,30,46], line:false, halftone:false } };
const st = STY[P.style] || STY.ochre;
const shift = c => [hw(c[0] + ho), c[1], c[2]];

const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const arc = [.2,.4,.6,.8,.35,.6,.9,.45][sec];
const ACT = { day:{ dk:.05+arc*.15, storm:.2 }, dusk:{ dk:.22+arc*.30, storm:.2 }, storm:{ dk:.15+arc*.2, storm:.6+arc*.4 } };
const act = ACT[P.act] || ACT.day;
const stormAmt = act.storm + P.density * 0.5;

const horY = height * P.y;

// ---- cached sky + dunes + stars ----
const key = width + 'x' + height + P.style + P.seed + Math.round(P.hue) + Math.round(P.y*20);
if (!S.bg || S.key !== key) {
  if (!S.bg) S.bg = createGraphics(width, height); else S.bg.resizeCanvas(width, height);
  const g = S.bg; g.colorMode(g.HSB, 360, 100, 100, 100); g.noStroke();
  const c = st.sky.map(shift);
  const hy = height * P.y;
  for (let yy = 0; yy < height; yy++) {
    const t = yy / Math.max(1, hy); let col;
    if (yy < hy) { if (t < 0.6) col = lerp3(c[0], c[1], t/0.6); else col = lerp3(c[1], c[2], (t-0.6)/0.4); }
    else col = shift(st.dune[0]);
    g.fill(col[0], col[1], col[2]); g.rect(0, yy, width, 1);
  }
  // stars
  const ns = 40 + Math.floor(P.seed % 30);
  for (let i = 0; i < ns; i++) { g.fill(hw(st.moon[0]+ho), 8, st.line?90:88, 22*fr(i*4+1)); g.rect(fr(i*4+2)*width, fr(i*4+3)*height*P.y*0.7, 1.2, 1.2); }
  // dune ridges (parallax layers)
  const dc = st.dune.map(shift);
  for (let L = 0; L < 3; L++) {
    const ry = hy + (height - hy) * (L * 0.32);
    const amp = u * (0.03 + L * 0.02);
    g.fill(dc[L][0], dc[L][1], dc[L][2]);
    g.beginShape(); g.vertex(-10, height+10); g.vertex(-10, ry);
    for (let sx = 0; sx <= width+40; sx += 34) {
      const n = Math.sin(sx*0.006 + L*2 + fr(L*11)*6) + 0.5*Math.sin(sx*0.015 + L);
      g.vertex(sx, ry - n*amp);
    }
    g.vertex(width+10, height+10); g.endShape(g.CLOSE);
    if (st.line) { g.stroke(dc[L][0], dc[L][1], 96, 40); g.strokeWeight(1); g.noFill();
      g.beginShape(); g.vertex(-10, ry);
      for (let sx = 0; sx <= width+40; sx += 34) { const n = Math.sin(sx*0.006 + L*2 + fr(L*11)*6) + 0.5*Math.sin(sx*0.015 + L); g.vertex(sx, ry - n*amp); }
      g.endShape(); g.noStroke(); }
  }
  S.key = key;
}
image(S.bg, 0, 0);

// ---- twin moons crossing (continuous, long period) ----
push(); noStroke();
const moons = [ { per: 88, r: 0.05, sat: 0.9, ph: 0.2 }, { per: 205, r: 0.033, sat: 0.6, ph: 0.6 } ];
for (let m = 0; m < 2; m++) {
  const mo = moons[m];
  const ph = ((K.t * P.speed / mo.per + mo.ph) % 1 + 1) % 1;
  const mx = ph * (width + u*0.2) - u*0.1;
  const my = horY * (0.62 - 0.42 * Math.sin(ph * Math.PI));
  const mr = u * mo.r;
  const mc = shift(st.moon);
  fill(mc[0], mc[1]*mo.sat, mc[2], 96); ellipse(mx, my, mr, mr);
  // crescent shadow (sky-toned cut-out)
  const sh = shift(st.sky[1]);
  fill(sh[0], sh[1], sh[2], 55);
  ellipse(mx + mr*0.22, my - mr*0.1, mr*0.92, mr*0.92);
  // craters
  fill(mc[0], mc[1]*mo.sat, mc[2]*0.8, 50);
  ellipse(mx - mr*0.18, my + mr*0.12, mr*0.2, mr*0.2);
  ellipse(mx + mr*0.05, my - mr*0.18, mr*0.14, mr*0.14);
}
pop();

// ---- dome (colony) ----
const dx = P.x * width, dy = horY;
const dr = u * (0.26 + P.scale * 0.18);
const dcol = shift(st.dome), gl = shift(st.glass);
push();
// interior warm glow (ADD, flicker)
blendMode(ADD); noStroke();
const flick = 0.7 + 0.3*Math.sin(K.t*3.1) + 0.15*Math.sin(K.t*7.7) + 0.4*A.bass + 0.3*K.swell;
const gv = P.glow * flick * (st.line ? 22 : 48);
for (let r = 0; r < 4; r++) { fill(gl[0], gl[1]*0.8, gl[2], gv*(1-r*0.2)); ellipse(dx, dy, dr*(1.1 - r*0.2), dr*(0.9 - r*0.16)); }
blendMode(BLEND);
// glass dome body
noStroke(); fill(dcol[0], dcol[1]*0.5, dcol[2]*0.55, st.line ? 0 : 40);
arc(dx, dy, dr*2, dr*2, Math.PI, TAU, CHORD);
// struts
stroke(dcol[0], dcol[1], dcol[2], 90); strokeWeight(Math.max(1, u*0.0022)); noFill();
arc(dx, dy, dr*2, dr*2, Math.PI, TAU);
const ribs = 6;
for (let i = 1; i < ribs; i++) { const a = Math.PI + Math.PI * (i/ribs); line(dx, dy, dx + Math.cos(a)*dr, dy + Math.sin(a)*dr); }
for (let ring = 1; ring < 3; ring++) { const rr = dr * ring/3; arc(dx, dy, rr*2, rr*2, Math.PI, TAU); }
// warm windows glinting on the dome
noStroke();
for (let i = 0; i < 5; i++) {
  const a = Math.PI + Math.PI * ((i+1)/6);
  const rr = dr * (0.4 + fr(i*3)*0.45);
  const wx = dx + Math.cos(a)*rr, wy = dy + Math.sin(a)*rr;
  const tw = 0.5 + 0.5*Math.sin(K.t*(2+i*0.7) + i) + 0.5*A.treble;
  fill(gl[0], gl[1], gl[2], 40 + 50*tw*P.glow);
  ellipse(wx, wy, u*0.012, u*0.012);
}
pop();

// ---- dust devils (drift + swirl, continuous) ----
push();
const nd = Math.max(0, Math.min(5, Math.round(P.dust)));
const dcl = shift(st.dust);
if (st.line) blendMode(BLEND); else blendMode(ADD);
for (let i = 0; i < nd; i++) {
  const per = 40 + i*17;
  const ph = ((K.t * P.speed / per + fr(i*9)) % 1 + 1) % 1;
  const cx = ph * (width + u*0.3) - u*0.15;
  const baseY = horY + (height - horY) * (0.15 + fr(i*5)*0.5);
  const dh = u * (0.28 + fr(i*7)*0.25) * (0.6 + P.energy);
  const dw = u * (0.03 + fr(i*3)*0.02) * (0.7 + stormAmt);
  const steps = 12;
  for (let s = 0; s < steps; s++) {
    const t = s / steps;
    const yy = baseY - t * dh;
    const sway = Math.sin(K.t * (2 + P.energy*3) + t * 6 + i) * dw * (1 + t*2) * (0.5 + P.energy);
    const rw = dw * (0.4 + t * 1.6);
    fill(dcl[0], dcl[1], dcl[2], (st.line ? 14 : 22) * (1 - t*0.7) * (0.4 + stormAmt) * (0.5 + P.energy*0.8));
    ellipse(cx + sway, yy, rw, rw * 1.4);
  }
}
blendMode(BLEND);
pop();

// ---- horizon haze / dust storm veil (density) ----
push(); noStroke();
const hz = shift(st.dust);
const hazeN = 3;
for (let i = 0; i < hazeN; i++) {
  const hy2 = horY - u*0.05 + (height - horY + u*0.1) * (i/hazeN);
  const a = (6 + P.density * 26) * (0.5 + 0.5*Math.sin(K.t*0.06 + i*1.9)) * (0.4 + stormAmt);
  fill(hz[0], hz[1]*0.7, hz[2], a);
  rect(0, hy2, width, (height - horY) * 0.6);
}
// day-dark tint
fill(hw(240+ho), 24, 6, 40*act.dk); rect(0,0,width,height);
pop();
blendMode(BLEND);
